static void RigidBodyTree_getBodyParentFrameName(const emlrtStack *sp,
  robotics_manip_internal_RigidBodyTree *obj, char_T parentframename_data[],
  int32_T parentframename_size[2])
{
  coder_array_boolean_T_2D namesIdx;
  coder_array_uint8_T_2D obj_FrameNames;
  emlrtStack st;
  robotics_manip_internal_RigidBody *parent;
  real_T pid;
  int32_T i;
  int32_T loop_ub;
  int32_T trueCount;
  uint8_T tmp_data[200];
  boolean_T bv[200];
  boolean_T b_b;
  st.prev = sp;
  st.tls = sp->tls;
  pid = obj->Bodies[2]->ParentIndex;
  if (pid == 0.0) {
    parent = &obj->Base;
  } else {
    i = (int32_T)emlrtIntegerCheckR2012b(pid, &j_emlrtDCI, (emlrtConstCTX)sp) -
      1;
    parent = obj->Bodies[emlrtDynamicBoundsCheckR2012b(i, 0, 11, &o_emlrtBCI,
      (emlrtConstCTX)sp)];
  }

  st.site = &sd_emlrtRSI;
  array_uint8_T_2D_Constructor(&obj_FrameNames);
  array_uint8_T_2D_SetSize(&obj_FrameNames,
    parent->FramesInternal.FrameNames.size[0], 200);
  loop_ub = parent->FramesInternal.FrameNames.size[0] * 200;
  for (i = 0; i < loop_ub; i++) {
    obj_FrameNames.vector.data[i] =
      parent->FramesInternal.FrameNames.vector.data[i];
  }

  pid = obj->BodyParentFrameIdx[2];
  array_boolean_T_2D_Constructor(&namesIdx);
  array_boolean_T_2D_SetSize(&namesIdx, obj_FrameNames.size[0], 200);
  loop_ub = obj_FrameNames.size[0] * 200;
  for (i = 0; i < loop_ub; i++) {
    namesIdx.vector.data[i] = (obj_FrameNames.vector.data[i] != 0);
  }

  loop_ub = emlrtDynamicBoundsCheckR2012b((int32_T)pid, 1, namesIdx.size[0],
    &m_emlrtBCI, &st);
  for (i = 0; i < 200; i++) {
    bv[i] = namesIdx.vector.data[(loop_ub + namesIdx.size[0] * i) - 1];
  }

  array_boolean_T_2D_Destructor(&namesIdx);
  i = (int32_T)emlrtIntegerCheckR2012b(pid, &i_emlrtDCI, &st);
  emlrtDynamicBoundsCheckR2012b(i, 1, obj_FrameNames.size[0], &l_emlrtBCI, &st);
  trueCount = 0;
  loop_ub = 0;
  for (i = 0; i < 200; i++) {
    b_b = bv[i];
    if (b_b) {
      trueCount++;
      tmp_data[loop_ub] = (uint8_T)i;
      loop_ub++;
    }
  }

  parentframename_size[0] = 1;
  parentframename_size[1] = trueCount;
  for (i = 0; i < trueCount; i++) {
    parentframename_data[i] = (char_T)(int8_T)obj_FrameNames.vector.data
      [((int32_T)pid + obj_FrameNames.size[0] * tmp_data[i]) - 1];
  }

  array_uint8_T_2D_Destructor(&obj_FrameNames);
}

