static void FrameTree_transformUsingFrameID(const emlrtStack *sp,
  coder_array_real_T *obj_FrameParents, coder_array_real_T_3D
  *obj_FrameRigidTransforms, real_T fid1, real_T tform[16])
{
  static int8_T iv[4] = { 0, 0, 0, 1 };

  __m128d r;
  __m128d r1;
  __m128d r2;
  emlrtStack st;
  real_T T1[16];
  real_T T2[16];
  real_T d_R[16];
  real_T R[9];
  real_T b_R[9];
  real_T c_R[3];
  real_T d;
  real_T fid;
  int32_T b_fid1;
  int32_T i;
  int32_T i1;
  int32_T i2;
  st.prev = sp;
  st.tls = sp->tls;
  if (fid1 == 1.0) {
    for (i = 0; i < 16; i++) {
      tform[i] = 0.0;
    }

    for (b_fid1 = 0; b_fid1 < 4; b_fid1++) {
      tform[b_fid1 + (b_fid1 << 2)] = 1.0;
    }
  } else {
    st.site = &hh_emlrtRSI;
    fid = fid1;
    i = (int32_T)emlrtIntegerCheckR2012b(fid1, &xb_emlrtDCI, &st);
    b_fid1 = emlrtDynamicBoundsCheckR2012b(i, 1, obj_FrameRigidTransforms->size
      [2], &ic_emlrtBCI, &st);
    for (i = 0; i < 4; i++) {
      for (i1 = 0; i1 < 4; i1++) {
        T1[i1 + (i << 2)] = obj_FrameRigidTransforms->vector.data[(i1 + (i << 2))
          + ((b_fid1 - 1) << 4)];
      }
    }

    while (fid > 1.0) {
      emlrtDynamicBoundsCheckR2012b((int32_T)fid, 1, obj_FrameParents->size[0],
        &kc_emlrtBCI, &st);
      d = obj_FrameParents->vector.data[(int32_T)fid - 1];
      i = (int32_T)emlrtIntegerCheckR2012b(d, &wb_emlrtDCI, &st);
      emlrtDynamicBoundsCheckR2012b(i, 1, obj_FrameRigidTransforms->size[2],
        &jc_emlrtBCI, &st);
      b_fid1 = (int32_T)obj_FrameParents->vector.data[(int32_T)fid - 1];
      memset(&T2[0], 0, sizeof(real_T) << 4);
      for (i = 0; i < 4; i++) {
        for (i1 = 0; i1 < 4; i1++) {
          d = T1[i1 + (i << 2)];
          for (i2 = 0; i2 < 4; i2++) {
            T2[i2 + (i << 2)] += obj_FrameRigidTransforms->vector.data[(i2 + (i1
              << 2)) + ((b_fid1 - 1) << 4)] * d;
          }
        }
      }

      memcpy(&T1[0], &T2[0], sizeof(real_T) << 4);
      fid = obj_FrameParents->vector.data[(int32_T)fid - 1];
    }

    st.site = &ih_emlrtRSI;
    emlrtDynamicBoundsCheckR2012b(1, 1, obj_FrameRigidTransforms->size[2],
      &ic_emlrtBCI, &st);
    for (i = 0; i < 4; i++) {
      for (i1 = 0; i1 < 4; i1++) {
        T2[i1 + (i << 2)] = obj_FrameRigidTransforms->vector.data[i1 + (i << 2)];
      }
    }

    for (i = 0; i < 3; i++) {
      for (i1 = 0; i1 < 3; i1++) {
        R[i1 + 3 * i] = T2[i + (i1 << 2)];
      }
    }

    for (i = 0; i <= 6; i += 2) {
      r = _mm_loadu_pd(&R[i]);
      _mm_storeu_pd(&b_R[i], _mm_mul_pd(r, _mm_set1_pd(-1.0)));
    }

    for (i = 8; i < 9; i++) {
      b_R[8] = -R[8];
    }

    memset(&c_R[0], 0, 3U * sizeof(real_T));
    for (i = 0; i < 3; i++) {
      for (i1 = 0; i1 <= 0; i1 += 2) {
        r = _mm_loadu_pd(&b_R[3 * i]);
        r1 = _mm_loadu_pd(&c_R[0]);
        r2 = _mm_loadu_pd(&R[3 * i]);
        _mm_storeu_pd(&d_R[i << 2], r2);
        _mm_storeu_pd(&c_R[0], _mm_add_pd(r1, _mm_mul_pd(r, _mm_set1_pd(T2[i +
          12]))));
      }

      for (i1 = 2; i1 < 3; i1++) {
        d_R[(i << 2) + 2] = R[3 * i + 2];
        c_R[2] += b_R[3 * i + 2] * T2[i + 12];
      }
    }

    for (i = 0; i < 3; i++) {
      d_R[i + 12] = c_R[i];
    }

    for (i = 0; i < 4; i++) {
      d_R[(i << 2) + 3] = (real_T)iv[i];
    }

    memset(&tform[0], 0, sizeof(real_T) << 4);
    for (i = 0; i < 4; i++) {
      for (i1 = 0; i1 < 4; i1++) {
        d = T1[i1 + (i << 2)];
        for (i2 = 0; i2 <= 2; i2 += 2) {
          r = _mm_loadu_pd(&d_R[i2 + (i1 << 2)]);
          r1 = _mm_loadu_pd(&tform[i2 + (i << 2)]);
          _mm_storeu_pd(&tform[i2 + (i << 2)], _mm_add_pd(r1, _mm_mul_pd(r,
            _mm_set1_pd(d))));
        }
      }
    }
  }
}

static void tforminv(real_T T[16], real_T Tinv[16])
{
  static int8_T iv[4] = { 0, 0, 0, 1 };

  __m128d r;
  __m128d r1;
  __m128d r2;
  real_T R[9];
  real_T b_R[9];
  real_T c_R[3];
  int32_T i;
  int32_T i1;
  for (i = 0; i < 3; i++) {
    for (i1 = 0; i1 < 3; i1++) {
      R[i1 + 3 * i] = T[i + (i1 << 2)];
    }
  }

  for (i = 0; i <= 6; i += 2) {
    r = _mm_loadu_pd(&R[i]);
    _mm_storeu_pd(&b_R[i], _mm_mul_pd(r, _mm_set1_pd(-1.0)));
  }

  for (i = 8; i < 9; i++) {
    b_R[8] = -R[8];
  }

  memset(&c_R[0], 0, 3U * sizeof(real_T));
  for (i = 0; i < 3; i++) {
    for (i1 = 0; i1 <= 0; i1 += 2) {
      r = _mm_loadu_pd(&b_R[3 * i]);
      r1 = _mm_loadu_pd(&c_R[0]);
      r2 = _mm_loadu_pd(&R[3 * i]);
      _mm_storeu_pd(&Tinv[i << 2], r2);
      _mm_storeu_pd(&c_R[0], _mm_add_pd(r1, _mm_mul_pd(r, _mm_set1_pd(T[i + 12]))));
    }

    for (i1 = 2; i1 < 3; i1++) {
      Tinv[(i << 2) + 2] = R[3 * i + 2];
      c_R[2] += b_R[3 * i + 2] * T[i + 12];
    }
  }

  for (i = 0; i < 3; i++) {
    Tinv[i + 12] = c_R[i];
  }

  for (i = 0; i < 4; i++) {
    Tinv[(i << 2) + 3] = (real_T)iv[i];
  }
}

static void eml_find(const emlrtStack *sp, boolean_T x[12], int32_T i_data[],
                     int32_T i_size[1])
{
  emlrtStack st;
  int32_T iv[2];
  int32_T idx;
  int32_T ii;
  boolean_T exitg1;
  st.prev = sp;
  st.tls = sp->tls;
  idx = 0;
  ii = 0;
  exitg1 = false;
  while ((!exitg1) && (ii < 12)) {
    if (x[ii]) {
      idx++;
      i_data[idx - 1] = ii + 1;
      if (idx >= 12) {
        exitg1 = true;
      } else {
        ii++;
      }
    } else {
      ii++;
    }
  }

  if (idx < 1) {
    idx = 0;
  }

  iv[0] = 1;
  iv[1] = idx;
  st.site = &th_emlrtRSI;
  indexShapeCheck(&st, 12, iv);
  i_size[0] = idx;
}

static void indexShapeCheck(const emlrtStack *sp, int32_T matrixSize, int32_T
  indexSize[2])
{
  static const int32_T iv[2] = { 1, 30 };

  static const int32_T iv1[2] = { 1, 30 };

  static char_T b_u[30] = { 'C', 'o', 'd', 'e', 'r', ':', 'F', 'E', ':', 'P',
    'o', 't', 'e', 'n', 't', 'i', 'a', 'l', 'V', 'e', 'c', 't', 'o', 'r', 'V',
    'e', 'c', 't', 'o', 'r' };

  emlrtStack b_st;
  emlrtStack st;
  const mxArray *b_y;
  const mxArray *m;
  const mxArray *y;
  int32_T i;
  char_T u[30];
  boolean_T c;
  st.prev = sp;
  st.tls = sp->tls;
  b_st.prev = &st;
  b_st.tls = st.tls;
  if ((matrixSize == 1) && (indexSize[1] != 1)) {
    c = true;
  } else {
    c = false;
  }

  st.site = &uh_emlrtRSI;
  if (c) {
    for (i = 0; i < 30; i++) {
      u[i] = b_u[i];
    }

    y = NULL;
    m = emlrtCreateCharArray(2, &iv[0]);
    emlrtInitCharArrayR2013a(&st, 30, m, &u[0]);
    emlrtAssign(&y, m);
    for (i = 0; i < 30; i++) {
      u[i] = b_u[i];
    }

    b_y = NULL;
    m = emlrtCreateCharArray(2, &iv1[0]);
    emlrtInitCharArrayR2013a(&st, 30, m, &u[0]);
    emlrtAssign(&b_y, m);
    b_st.site = &wp_emlrtRSI;
    b_error(&b_st, y, getString(&b_st, b_message(&b_st, b_y, &u_emlrtMCI),
             &u_emlrtMCI), &u_emlrtMCI);
  }
}

