static void normalizeRows(real_T b_matrix[3], real_T normRowMatrix[3])
{
  __m128d r;
  emlrtStack st;
  real_T y[3];
  real_T c_matrix;
  int32_T k;
  for (k = 0; k <= 0; k += 2) {
    r = _mm_loadu_pd(&b_matrix[0]);
    _mm_storeu_pd(&y[0], _mm_mul_pd(r, r));
  }

  for (k = 2; k < 3; k++) {
    c_matrix = b_matrix[2];
    y[2] = c_matrix * c_matrix;
  }

  c_matrix = sumColumnB(y);
  st.site = &gk_emlrtRSI;
  b_sqrt(&c_matrix);
  c_matrix = 1.0 / c_matrix;
  for (k = 0; k <= 0; k += 2) {
    r = _mm_loadu_pd(&b_matrix[0]);
    _mm_storeu_pd(&normRowMatrix[0], _mm_mul_pd(r, _mm_set1_pd(c_matrix)));
  }

  for (k = 2; k < 3; k++) {
    normRowMatrix[2] = b_matrix[2] * c_matrix;
  }
}

static real_T sumColumnB(real_T x[3])
{
  real_T y;
  int32_T k;
  y = x[0];
  for (k = 0; k < 2; k++) {
    y += x[k + 1];
  }

  return y;
}

static void b_cat(real_T varargin_1, real_T varargin_2, real_T varargin_3,
                  real_T varargin_4, real_T varargin_5, real_T varargin_6,
                  real_T varargin_7, real_T varargin_8, real_T varargin_9,
                  real_T y[9])
{
  y[0] = varargin_1;
  y[1] = varargin_2;
  y[2] = varargin_3;
  y[3] = varargin_4;
  y[4] = varargin_5;
  y[5] = varargin_6;
  y[6] = varargin_7;
  y[7] = varargin_8;
  y[8] = varargin_9;
}

static void permute(real_T a[9], real_T b_b[9])
{
  int32_T b_k;
  int32_T k;
  for (k = 0; k < 3; k++) {
    for (b_k = 0; b_k < 3; b_k++) {
      b_b[k + 3 * b_k] = a[b_k + 3 * k];
    }
  }
}

static void quat2tform(real_T q[4], real_T H[16])
{
  __m128d r;
  emlrtStack b_st;
  emlrtStack c_st;
  emlrtStack st;
  real_T dv[9];
  real_T dv1[9];
  real_T normRowMatrix[4];
  real_T b_b;
  int32_T i;
  int32_T k;
  st.site = &hk_emlrtRSI;
  b_st.site = &ik_emlrtRSI;
  for (k = 0; k <= 2; k += 2) {
    r = _mm_loadu_pd(&q[k]);
    _mm_storeu_pd(&normRowMatrix[k], _mm_mul_pd(r, r));
  }

  b_b = b_sumColumnB(normRowMatrix);
  c_st.site = &gk_emlrtRSI;
  b_sqrt(&b_b);
  b_b = 1.0 / b_b;
  for (k = 0; k <= 2; k += 2) {
    r = _mm_loadu_pd(&q[k]);
    _mm_storeu_pd(&normRowMatrix[k], _mm_mul_pd(r, _mm_set1_pd(b_b)));
  }

  for (k = 0; k < 16; k++) {
    H[k] = 0.0;
  }

  b_cat(1.0 - 2.0 * (normRowMatrix[2] * normRowMatrix[2] + normRowMatrix[3] *
                     normRowMatrix[3]), 2.0 * (normRowMatrix[1] * normRowMatrix
         [2] - normRowMatrix[0] * normRowMatrix[3]), 2.0 * (normRowMatrix[1] *
         normRowMatrix[3] + normRowMatrix[0] * normRowMatrix[2]), 2.0 *
        (normRowMatrix[1] * normRowMatrix[2] + normRowMatrix[0] * normRowMatrix
         [3]), 1.0 - 2.0 * (normRowMatrix[1] * normRowMatrix[1] + normRowMatrix
         [3] * normRowMatrix[3]), 2.0 * (normRowMatrix[2] * normRowMatrix[3] -
         normRowMatrix[0] * normRowMatrix[1]), 2.0 * (normRowMatrix[1] *
         normRowMatrix[3] - normRowMatrix[0] * normRowMatrix[2]), 2.0 *
        (normRowMatrix[2] * normRowMatrix[3] + normRowMatrix[0] * normRowMatrix
         [1]), 1.0 - 2.0 * (normRowMatrix[1] * normRowMatrix[1] + normRowMatrix
         [2] * normRowMatrix[2]), dv1);
  permute(dv1, dv);
  for (k = 0; k < 3; k++) {
    for (i = 0; i < 3; i++) {
      H[i + (k << 2)] = dv[i + 3 * k];
    }
  }

  H[15] = 1.0;
}

static real_T b_sumColumnB(real_T x[4])
{
  real_T y;
  int32_T k;
  y = x[0];
  for (k = 0; k < 3; k++) {
    y += x[k + 1];
  }

  return y;
}

