  const mxArray *y;
  real_T a[16];
  real_T b_I[16];
  real_T b_b[16];
  real_T c_b[16];
  real_T dv[9];
  real_T dv1[9];
  real_T result_data[4];
  real_T v[3];
  real_T cth;
  real_T sth;
  int32_T switch_expression_size[2];
  int32_T i;
  int32_T i1;
  int32_T loop_ub;
  char_T obj_Vector[200];
