static void tformToSpatialXform(real_T T[16], real_T X[36])
{
  __m128d r;
  __m128d r1;
  real_T R[9];
  real_T dv[9];
  real_T dv1[9];
  real_T d;
  int32_T i;
  int32_T i1;
  int32_T i2;
  dv[0] = 0.0;
  dv[3] = -T[14];
  dv[6] = T[13];
  dv[1] = T[14];
  dv[4] = 0.0;
  dv[7] = -T[12];
  dv[2] = -T[13];
  dv[5] = T[12];
  dv[8] = 0.0;
  memset(&dv1[0], 0, 9U * sizeof(real_T));
  for (i = 0; i < 3; i++) {
    for (i1 = 0; i1 < 3; i1++) {
      R[i1 + 3 * i] = T[i1 + (i << 2)];
      d = R[i1 + 3 * i];
      for (i2 = 0; i2 <= 0; i2 += 2) {
        r = _mm_loadu_pd(&dv[3 * i1]);
        r1 = _mm_loadu_pd(&dv1[3 * i]);
        _mm_storeu_pd(&dv1[3 * i], _mm_add_pd(r1, _mm_mul_pd(r, _mm_set1_pd(d))));
      }

      for (i2 = 2; i2 < 3; i2++) {
        dv1[3 * i + 2] += dv[3 * i1 + 2] * d;
      }

      X[i1 + 6 * i] = R[i1 + 3 * i];
      X[i1 + 6 * (i + 3)] = 0.0;
    }

    for (i1 = 0; i1 < 3; i1++) {
      X[(i1 + 6 * i) + 3] = dv1[i1 + 3 * i];
      X[(i1 + 6 * (i + 3)) + 3] = R[i1 + 3 * i];
    }
  }
}

static void mtimes(real_T A[36], real_T B_data[], int32_T B_size[2], real_T
                   C_data[], int32_T C_size[2])
{
  ptrdiff_t k_t;
  ptrdiff_t lda_t;
  ptrdiff_t ldb_t;
  ptrdiff_t ldc_t;
  ptrdiff_t m_t;
  ptrdiff_t n_t;
  coder_array_real_T_2D C;
  real_T alpha1;
  real_T beta1;
  int32_T loop_ub;
  char_T TRANSA1;
  char_T TRANSB1;
  if (B_size[1] == 0) {
    C_size[0] = 6;
    C_size[1] = 0;
  } else {
    TRANSB1 = 'N';
    TRANSA1 = 'N';
    alpha1 = 1.0;
    beta1 = 0.0;
    m_t = (ptrdiff_t)6;
    n_t = (ptrdiff_t)B_size[1];
    k_t = (ptrdiff_t)6;
    lda_t = (ptrdiff_t)6;
    ldb_t = (ptrdiff_t)6;
    ldc_t = (ptrdiff_t)6;
    array_real_T_2D_Constructor(&C);
    array_real_T_2D_SetSize(&C, 6, B_size[1]);
    dgemm(&TRANSA1, &TRANSB1, &m_t, &n_t, &k_t, &alpha1, &A[0], &lda_t, &B_data
          [0], &ldb_t, &beta1, &C.vector.data[0], &ldc_t);
    C_size[0] = 6;
    C_size[1] = C.size[1];
    loop_ub = 6 * C.size[1];
    if (loop_ub - 1 >= 0) {
      memcpy(&C_data[0], &C.vector.data[0], (uint32_T)loop_ub * sizeof(real_T));
    }

    array_real_T_2D_Destructor(&C);
  }
}

static void b_mtimes(real_T A[36], coder_array_real_T_2D *B,
                     coder_array_real_T_2D *C)
{
  ptrdiff_t k_t;
  ptrdiff_t lda_t;
  ptrdiff_t ldb_t;
  ptrdiff_t ldc_t;
  ptrdiff_t m_t;
  ptrdiff_t n_t;
  real_T alpha1;
  real_T beta1;
  char_T TRANSA1;
  char_T TRANSB1;
  if (B->size[1] == 0) {
    array_real_T_2D_SetSize(C, 6, 0);
  } else {
    TRANSB1 = 'N';
    TRANSA1 = 'N';
    alpha1 = 1.0;
    beta1 = 0.0;
    m_t = (ptrdiff_t)6;
    n_t = (ptrdiff_t)B->size[1];
    k_t = (ptrdiff_t)6;
    lda_t = (ptrdiff_t)6;
    ldb_t = (ptrdiff_t)6;
    ldc_t = (ptrdiff_t)6;
    array_real_T_2D_SetSize(C, 6, B->size[1]);
    dgemm(&TRANSA1, &TRANSB1, &m_t, &n_t, &k_t, &alpha1, &A[0], &lda_t,
          &B->vector.data[0], &ldb_t, &beta1, &C->vector.data[0], &ldc_t);
  }
}

