      array_boolean_T_SetSize(&b_s, s.size[0]);
      loop_ub = s.size[0];
      for (i = 0; i < loop_ub; i++) {
        b_s.vector.data[i] = (s.vector.data[i] >=
                              obj->ConstraintBound.vector.data[i]);
      }

      array_boolean_T_SetSize(&b_x, b_s.size[0]);
