static void d_mtimes(coder_array_real_T_2D *A, real_T B[12], coder_array_real_T *
                     C)
{
  ptrdiff_t k_t;
  ptrdiff_t lda_t;
  ptrdiff_t ldb_t;
  ptrdiff_t ldc_t;
  ptrdiff_t m_t;
  ptrdiff_t n_t;
  real_T alpha1;
  real_T beta1;
  int32_T i;
  int32_T loop_ub;
  char_T TRANSA1;
  char_T TRANSB1;
  if ((A->size[0] == 0) || (A->size[1] == 0)) {
    array_real_T_SetSize(C, A->size[1]);
    loop_ub = A->size[1];
    for (i = 0; i < loop_ub; i++) {
      C->vector.data[i] = 0.0;
    }
  } else {
    TRANSB1 = 'N';
    TRANSA1 = 'T';
    alpha1 = 1.0;
    beta1 = 0.0;
    m_t = (ptrdiff_t)A->size[1];
    n_t = (ptrdiff_t)1;
    k_t = (ptrdiff_t)12;
    lda_t = (ptrdiff_t)A->size[0];
    ldb_t = (ptrdiff_t)12;
    ldc_t = (ptrdiff_t)A->size[1];
    array_real_T_SetSize(C, A->size[1]);
    dgemm(&TRANSA1, &TRANSB1, &m_t, &n_t, &k_t, &alpha1, &A->vector.data[0],
          &lda_t, &B[0], &ldb_t, &beta1, &C->vector.data[0], &ldc_t);
  }
}

static void b_eml_find(const emlrtStack *sp, coder_array_boolean_T *x,
  coder_array_int32_T *i)
{
  static const int32_T iv1[2] = { 1, 30 };

  static const int32_T iv2[2] = { 1, 30 };

  static char_T b_u[30] = { 'C', 'o', 'd', 'e', 'r', ':', 'b', 'u', 'i', 'l',
    't', 'i', 'n', 's', ':', 'A', 's', 's', 'e', 'r', 't', 'i', 'o', 'n', 'F',
    'a', 'i', 'l', 'e', 'd' };

  emlrtStack st;
  const mxArray *b_y;
  const mxArray *m;
  const mxArray *y;
  int32_T iv[2];
  int32_T idx;
  int32_T ii;
  int32_T nx;
  char_T u[30];
  boolean_T exitg1;
  st.prev = sp;
  st.tls = sp->tls;
  nx = x->size[0];
  idx = 0;
  array_int32_T_SetSize(i, x->size[0]);
  ii = 0;
  exitg1 = false;
  while ((!exitg1) && (ii <= nx - 1)) {
    if (x->vector.data[ii]) {
      idx++;
      i->vector.data[idx - 1] = ii + 1;
      if (idx >= nx) {
        exitg1 = true;
      } else {
        ii++;
      }
    } else {
      ii++;
    }
  }

  if (idx > x->size[0]) {
    for (nx = 0; nx < 30; nx++) {
      u[nx] = b_u[nx];
    }

    y = NULL;
    m = emlrtCreateCharArray(2, &iv1[0]);
    emlrtInitCharArrayR2013a((emlrtConstCTX)sp, 30, m, &u[0]);
    emlrtAssign(&y, m);
    for (nx = 0; nx < 30; nx++) {
      u[nx] = b_u[nx];
    }

    b_y = NULL;
    m = emlrtCreateCharArray(2, &iv2[0]);
    emlrtInitCharArrayR2013a((emlrtConstCTX)sp, 30, m, &u[0]);
    emlrtAssign(&b_y, m);
    st.site = &qp_emlrtRSI;
    b_error(&st, y, getString(&st, b_message(&st, b_y, &gb_emlrtMCI),
             &gb_emlrtMCI), &gb_emlrtMCI);
  }

  if (x->size[0] == 1) {
    if (idx == 0) {
      array_int32_T_SetSize(i, 0);
    }
  } else {
    if (idx < 1) {
      idx = 0;
    }

    iv[0] = 1;
    iv[1] = idx;
    st.site = &th_emlrtRSI;
    indexShapeCheck(&st, i->size[0], iv);
    array_int32_T_SetSize(i, idx);
  }
}

static void xgeqp3(coder_array_real_T_2D *A, coder_array_real_T_2D *b_A,
                   coder_array_real_T *tau, coder_array_int32_T_2D *jpvt)
{
  ptrdiff_t info_t;
  coder_array_int32_T_2D b_jpvt;
  coder_array_ptrdiff_t jpvt_t;
  coder_array_real_T_2D c_A;
  int32_T i;
  int32_T ma;
  int32_T minmana;
  int32_T minmn;
  int32_T na;
  array_real_T_2D_SetSize(b_A, A->size[0], A->size[1]);
  minmn = A->size[0] * A->size[1];
  for (i = 0; i < minmn; i++) {
    b_A->vector.data[i] = A->vector.data[i];
  }

  ma = b_A->size[0];
  na = b_A->size[1] - 1;
  array_int32_T_2D_Constructor(&b_jpvt);
  array_int32_T_2D_SetSize(&b_jpvt, 1, b_A->size[1]);
  minmn = b_A->size[1];
  for (i = 0; i < minmn; i++) {
    b_jpvt.vector.data[i] = 0;
  }

  array_real_T_2D_Constructor(&c_A);
  array_real_T_2D_SetSize(&c_A, b_A->size[0], b_A->size[1]);
  minmn = b_A->size[0] * b_A->size[1];
  for (i = 0; i < minmn; i++) {
    c_A.vector.data[i] = b_A->vector.data[i];
  }

  minmana = muIntScalarMin_sint32(c_A.size[0], c_A.size[1]);
  array_real_T_SetSize(tau, minmana);
  array_ptrdiff_t_Constructor(&jpvt_t);
  if ((c_A.size[0] == 0) || (c_A.size[1] == 0) || (b_A->size[0] < 1) ||
      (b_A->size[1] < 1)) {
    minmn = tau->size[0];
    array_real_T_SetSize(tau, minmn);
    for (i = 0; i < minmn; i++) {
      tau->vector.data[i] = 0.0;
    }

    for (ma = 0; ma <= na; ma++) {
      b_jpvt.vector.data[ma] = ma + 1;
    }
  } else {
    array_ptrdiff_t_SetSize(&jpvt_t, b_A->size[1]);
    minmn = b_A->size[1];
    for (i = 0; i < minmn; i++) {
      jpvt_t.vector.data[i] = (ptrdiff_t)0;
    }

    info_t = LAPACKE_dgeqp3(102, (ptrdiff_t)b_A->size[0], (ptrdiff_t)b_A->size[1],
      &c_A.vector.data[0], (ptrdiff_t)c_A.size[0], &jpvt_t.vector.data[0],
      &tau->vector.data[0]);
    if ((int32_T)info_t != 0) {
      for (minmn = 0; minmn <= na; minmn++) {
        for (i = 0; i < ma; i++) {
          c_A.vector.data[minmn * c_A.size[0] + i] = rtNaN;
        }
      }

      minmn = na + 1;
      minmn = muIntScalarMin_sint32(ma, minmn) - 1;
      for (ma = 0; ma <= minmn; ma++) {
        tau->vector.data[ma] = rtNaN;
      }

      i = minmn + 2;
      for (ma = i; ma <= minmana; ma++) {
        tau->vector.data[ma - 1] = 0.0;
      }

      for (ma = 0; ma <= na; ma++) {
        b_jpvt.vector.data[ma] = ma + 1;
      }
    } else {
      for (ma = 0; ma <= na; ma++) {
        b_jpvt.vector.data[ma] = (int32_T)jpvt_t.vector.data[ma];
      }
    }
  }

  array_ptrdiff_t_Destructor(&jpvt_t);
  array_real_T_2D_SetSize(b_A, c_A.size[0], c_A.size[1]);
  minmn = c_A.size[0] * c_A.size[1];
  for (i = 0; i < minmn; i++) {
    b_A->vector.data[i] = c_A.vector.data[i];
  }

  array_real_T_2D_Destructor(&c_A);
  array_int32_T_2D_SetSize(jpvt, 1, b_jpvt.size[1]);
  minmn = b_jpvt.size[1];
  for (i = 0; i < minmn; i++) {
    jpvt->vector.data[i] = b_jpvt.vector.data[i];
  }

  array_int32_T_2D_Destructor(&b_jpvt);
}

static void xorgqr(int32_T m, int32_T n, int32_T k, coder_array_real_T_2D *A,
                   int32_T lda, coder_array_real_T *tau, coder_array_real_T_2D
                   *b_A)
{
  ptrdiff_t info_t;
  int32_T c_A[2];
  int32_T i;
  int32_T loop_ub;
  array_real_T_2D_SetSize(b_A, A->size[0], A->size[1]);
  loop_ub = A->size[0] * A->size[1];
  for (i = 0; i < loop_ub; i++) {
    b_A->vector.data[i] = A->vector.data[i];
  }

  if ((b_A->size[0] != 0) && (b_A->size[1] != 0)) {
    info_t = LAPACKE_dorgqr(102, (ptrdiff_t)m, (ptrdiff_t)n, (ptrdiff_t)k,
      &b_A->vector.data[0], (ptrdiff_t)lda, &tau->vector.data[0]);
    if ((int32_T)info_t != 0) {
      for (i = 0; i < 2; i++) {
        c_A[i] = b_A->size[i];
      }

      array_real_T_2D_SetSize(b_A, c_A[0], c_A[1]);
      loop_ub = c_A[0] * c_A[1];
      for (i = 0; i < loop_ub; i++) {
        b_A->vector.data[i] = rtNaN;
      }
    }
  }
}

