static real_T toc(real_T tstart_tv_sec, real_T tstart_tv_nsec)
{
  emlrtStack b_st;
  emlrtStack c_st;
  emlrtStack st;
  emlrtTimespec tnow;
  st.site = &am_emlrtRSI;
  b_st.site = &ei_emlrtRSI;
  c_st.site = &fi_emlrtRSI;
  emlrtClockGettimeMonotonic(&tnow);
  return (tnow.tv_sec - tstart_tv_sec) + (tnow.tv_nsec - tstart_tv_nsec) /
    1.0E+9;
}

static real_T IKHelpers_evaluateSolution(const emlrtStack *sp,
  robotics_manip_internal_IKExtraArgs *args)
{
  static const int32_T iv[2] = { 1, 15 };

  static const int32_T iv1[2] = { 1, 45 };

  static const int32_T iv2[2] = { 1, 15 };

  static const int32_T iv3[2] = { 1, 45 };

  static char_T d_u[45] = { 'C', 'o', 'd', 'e', 'r', ':', 't', 'o', 'o', 'l',
    'b', 'o', 'x', ':', 'm', 't', 'i', 'm', 'e', 's', '_', 'n', 'o', 'D', 'y',
    'n', 'a', 'm', 'i', 'c', 'S', 'c', 'a', 'l', 'a', 'r', 'E', 'x', 'p', 'a',
    'n', 's', 'i', 'o', 'n' };

  static char_T c_u[15] = { 'M', 'A', 'T', 'L', 'A', 'B', ':', 'i', 'n', 'n',
    'e', 'r', 'd', 'i', 'm' };

  __m128d r;
  __m128d r1;
  coder_array_real_T b_b;
  emlrtStack b_st;
  emlrtStack st;
  const mxArray *b_y;
  const mxArray *c_y;
  const mxArray *d_y;
  const mxArray *e_y;
  const mxArray *m;
  real_T a[36];
  real_T y[6];
  real_T absxk;
  real_T en;
  real_T scale;
  real_T t;
  int32_T i;
  int32_T loop_ub;
  char_T b_u[45];
  char_T u[15];
  st.prev = sp;
  st.tls = sp->tls;
  b_st.prev = &st;
  b_st.tls = st.tls;
  for (i = 0; i < 36; i++) {
    a[i] = args->WeightMatrix[i];
  }

  array_real_T_Constructor(&b_b);
  array_real_T_SetSize(&b_b, args->ErrTemp.size[0]);
  loop_ub = args->ErrTemp.size[0];
  for (i = 0; i < loop_ub; i++) {
    b_b.vector.data[i] = args->ErrTemp.vector.data[i];
  }

  st.site = &fj_emlrtRSI;
  if (b_b.size[0] != 6) {
    if (b_b.size[0] == 1) {
      for (i = 0; i < 45; i++) {
        b_u[i] = d_u[i];
      }

      c_y = NULL;
      m = emlrtCreateCharArray(2, &iv1[0]);
      emlrtInitCharArrayR2013a(&st, 45, m, &b_u[0]);
      emlrtAssign(&c_y, m);
      for (i = 0; i < 45; i++) {
        b_u[i] = d_u[i];
      }

      e_y = NULL;
      m = emlrtCreateCharArray(2, &iv3[0]);
      emlrtInitCharArrayR2013a(&st, 45, m, &b_u[0]);
      emlrtAssign(&e_y, m);
      b_st.site = &hp_emlrtRSI;
      b_error(&b_st, c_y, getString(&b_st, b_message(&b_st, e_y, &ab_emlrtMCI),
               &ab_emlrtMCI), &ab_emlrtMCI);
    } else {
      for (i = 0; i < 15; i++) {
        u[i] = c_u[i];
      }

      b_y = NULL;
      m = emlrtCreateCharArray(2, &iv[0]);
      emlrtInitCharArrayR2013a(&st, 15, m, &u[0]);
      emlrtAssign(&b_y, m);
      for (i = 0; i < 15; i++) {
        u[i] = c_u[i];
      }

      d_y = NULL;
      m = emlrtCreateCharArray(2, &iv2[0]);
      emlrtInitCharArrayR2013a(&st, 15, m, &u[0]);
      emlrtAssign(&d_y, m);
      b_st.site = &ip_emlrtRSI;
      b_error(&b_st, b_y, getString(&b_st, b_message(&b_st, d_y, &y_emlrtMCI),
               &y_emlrtMCI), &y_emlrtMCI);
    }
  }

  memset(&y[0], 0, 6U * sizeof(real_T));
  for (i = 0; i < 6; i++) {
    scale = b_b.vector.data[i];
    for (loop_ub = 0; loop_ub <= 4; loop_ub += 2) {
      r = _mm_loadu_pd(&a[loop_ub + 6 * i]);
      r1 = _mm_loadu_pd(&y[loop_ub]);
      _mm_storeu_pd(&y[loop_ub], _mm_add_pd(r1, _mm_mul_pd(r, _mm_set1_pd(scale))));
    }
  }

  array_real_T_Destructor(&b_b);
  en = 0.0;
  scale = 3.3121686421112381E-170;
  for (loop_ub = 0; loop_ub < 6; loop_ub++) {
    absxk = muDoubleScalarAbs(y[loop_ub]);
    if (absxk > scale) {
      t = scale / absxk;
      en = en * t * t + 1.0;
      scale = absxk;
    } else {
      t = absxk / scale;
      en += t * t;
    }
  }

  return scale * muDoubleScalarSqrt(en);
}

