static void h_mtimes(coder_array_real_T_2D *A, coder_array_real_T_2D *B,
                     coder_array_real_T_2D *C)
{
  ptrdiff_t k_t;
  ptrdiff_t lda_t;
  ptrdiff_t ldb_t;
  ptrdiff_t ldc_t;
  ptrdiff_t m_t;
  ptrdiff_t n_t;
  real_T alpha1;
  real_T beta1;
  int32_T i;
  int32_T loop_ub;
  char_T TRANSA1;
  char_T TRANSB1;
  if ((A->size[0] == 0) || (A->size[1] == 0) || (B->size[0] == 0) || (B->size[1]
       == 0)) {
    array_real_T_2D_SetSize(C, A->size[1], B->size[1]);
    loop_ub = A->size[1] * B->size[1];
    for (i = 0; i < loop_ub; i++) {
      C->vector.data[i] = 0.0;
    }
  } else {
    TRANSB1 = 'N';
    TRANSA1 = 'T';
    alpha1 = 1.0;
    beta1 = 0.0;
    m_t = (ptrdiff_t)A->size[1];
    n_t = (ptrdiff_t)B->size[1];
    k_t = (ptrdiff_t)A->size[0];
    lda_t = (ptrdiff_t)A->size[0];
    ldb_t = (ptrdiff_t)B->size[0];
    ldc_t = (ptrdiff_t)A->size[1];
    array_real_T_2D_SetSize(C, A->size[1], B->size[1]);
    dgemm(&TRANSA1, &TRANSB1, &m_t, &n_t, &k_t, &alpha1, &A->vector.data[0],
          &lda_t, &B->vector.data[0], &ldb_t, &beta1, &C->vector.data[0], &ldc_t);
  }
}

static void mldivide(const emlrtStack *sp, coder_array_real_T_2D *A,
                     coder_array_real_T_2D *B, coder_array_real_T_2D *Y)
{
  static const int32_T iv[2] = { 1, 15 };

  static const int32_T iv1[2] = { 1, 15 };

  static const int32_T iv2[2] = { 1, 6 };

  static char_T b_u[15] = { 'M', 'A', 'T', 'L', 'A', 'B', ':', 'd', 'i', 'm',
    'a', 'g', 'r', 'e', 'e' };

  static char_T b_rfmt[6] = { '%', '1', '4', '.', '6', 'e' };

  ptrdiff_t INFO;
  ptrdiff_t LDA;
  ptrdiff_t nrc_t;
  coder_array_int32_T_2D jpvt;
  coder_array_ptrdiff_t IPIV;
  coder_array_real_T tau;
  coder_array_real_T_2D b_A;
  coder_array_real_T_2D b_B;
  emlrtStack b_st;
  emlrtStack c_st;
  emlrtStack d_st;
  emlrtStack e_st;
  emlrtStack st;
  const mxArray *b_y;
  const mxArray *c_y;
  const mxArray *d_y;
  const mxArray *m;
  const mxArray *y;
  real_T tol;
  int32_T c_B[2];
  int32_T b_i;
  int32_T b_m;
  int32_T i;
  int32_T j;
  int32_T k;
  int32_T maxmn;
  int32_T minmn;
  int32_T nb;
  int32_T rankA;
  uint32_T unnamed_idx_0;
  uint32_T unnamed_idx_1;
  char_T u[15];
  char_T str[14];
  char_T rfmt[6];
  st.prev = sp;
  st.tls = sp->tls;
  b_st.prev = &st;
  b_st.tls = st.tls;
  c_st.prev = &b_st;
  c_st.tls = b_st.tls;
  d_st.prev = &c_st;
  d_st.tls = c_st.tls;
  e_st.prev = &d_st;
  e_st.tls = d_st.tls;
  if (B->size[0] != A->size[0]) {
    for (i = 0; i < 15; i++) {
      u[i] = b_u[i];
    }

    y = NULL;
    m = emlrtCreateCharArray(2, &iv[0]);
    emlrtInitCharArrayR2013a((emlrtConstCTX)sp, 15, m, &u[0]);
    emlrtAssign(&y, m);
    for (i = 0; i < 15; i++) {
      u[i] = b_u[i];
    }

    b_y = NULL;
    m = emlrtCreateCharArray(2, &iv1[0]);
    emlrtInitCharArrayR2013a((emlrtConstCTX)sp, 15, m, &u[0]);
    emlrtAssign(&b_y, m);
    st.site = &pp_emlrtRSI;
    b_error(&st, y, getString(&st, b_message(&st, b_y, &jb_emlrtMCI),
             &jb_emlrtMCI), &jb_emlrtMCI);
  }

  st.site = &bm_emlrtRSI;
  array_real_T_2D_Constructor(&b_A);
  array_real_T_Constructor(&tau);
  array_int32_T_2D_Constructor(&jpvt);
  array_real_T_2D_Constructor(&b_B);
  array_ptrdiff_t_Constructor(&IPIV);
  if ((A->size[0] == 0) || (A->size[1] == 0) || ((B->size[0] == 0) || (B->size[1]
        == 0))) {
    unnamed_idx_0 = (uint32_T)A->size[1];
    unnamed_idx_1 = (uint32_T)B->size[1];
    array_real_T_2D_SetSize(Y, (int32_T)unnamed_idx_0, (int32_T)unnamed_idx_1);
    maxmn = (int32_T)unnamed_idx_0 * (int32_T)unnamed_idx_1;
    for (i = 0; i < maxmn; i++) {
      Y->vector.data[i] = 0.0;
    }
  } else if (A->size[0] == A->size[1]) {
    b_st.site = &cm_emlrtRSI;
    c_st.site = &fm_emlrtRSI;
    i = muIntScalarMin_sint32(A->size[0], A->size[1]);
    minmn = muIntScalarMin_sint32(B->size[0], i);
    array_real_T_2D_SetSize(&b_A, A->size[0], A->size[1]);
    maxmn = A->size[0] * A->size[1];
    for (i = 0; i < maxmn; i++) {
      b_A.vector.data[i] = A->vector.data[i];
    }

    array_real_T_2D_SetSize(&b_B, B->size[0], B->size[1]);
    maxmn = B->size[0] * B->size[1];
    for (i = 0; i < maxmn; i++) {
      b_B.vector.data[i] = B->vector.data[i];
    }

    d_st.site = &gm_emlrtRSI;
    b_repmat((ptrdiff_t)0.0, minmn, &IPIV);
    array_ptrdiff_t_SetSize(&IPIV, IPIV.size[0]);
    nrc_t = (ptrdiff_t)minmn;
    LDA = (ptrdiff_t)b_A.size[0];
    INFO = LAPACKE_dgetrf_work(102, nrc_t, nrc_t, &b_A.vector.data[0], LDA,
      &IPIV.vector.data[0]);
    if ((int32_T)INFO < 0) {
      for (i = 0; i < 2; i++) {
        c_B[i] = b_B.size[i];
      }

      array_real_T_2D_SetSize(&b_B, c_B[0], c_B[1]);
      maxmn = c_B[0] * c_B[1];
      for (i = 0; i < maxmn; i++) {
        b_B.vector.data[i] = rtNaN;
      }
    } else {
      LAPACKE_dgetrs_work(102, 'N', nrc_t, (ptrdiff_t)B->size[1],
                          &b_A.vector.data[0], LDA, &IPIV.vector.data[0],
                          &b_B.vector.data[0], (ptrdiff_t)b_B.size[0]);
    }

    array_real_T_2D_SetSize(Y, b_B.size[0], b_B.size[1]);
    maxmn = b_B.size[0] * b_B.size[1];
    for (i = 0; i < maxmn; i++) {
      Y->vector.data[i] = b_B.vector.data[i];
    }

    if (((A->size[0] != 1) || (A->size[1] != 1)) && ((int32_T)INFO > 0)) {
      c_st.site = &em_emlrtRSI;
      d_st.site = &rm_emlrtRSI;
      b_warning(&d_st);
    }
  } else {
    b_st.site = &dm_emlrtRSI;
    c_st.site = &sm_emlrtRSI;
    xgeqp3(A, &b_A, &tau, &jpvt);
    c_st.site = &tm_emlrtRSI;
    rankA = 0;
    tol = 0.0;
    if (b_A.size[0] < b_A.size[1]) {
      minmn = b_A.size[0];
      maxmn = b_A.size[1];
    } else {
      minmn = b_A.size[1];
      maxmn = b_A.size[0];
    }

    if (minmn > 0) {
      tol = muDoubleScalarMin(1.4901161193847656E-8, 2.2204460492503131E-15 *
        (real_T)maxmn) * muDoubleScalarAbs(b_A.vector.data[0]);
      while ((rankA < minmn) && (!(muDoubleScalarAbs(b_A.vector.data[rankA +
                b_A.size[0] * rankA]) <= tol))) {
        rankA++;
      }
    }

    if (rankA < minmn) {
      d_st.site = &vm_emlrtRSI;
      for (i = 0; i < 6; i++) {
        rfmt[i] = b_rfmt[i];
      }

      c_y = NULL;
      m = emlrtCreateCharArray(2, &iv2[0]);
      emlrtInitCharArrayR2013a(&d_st, 6, m, &rfmt[0]);
      emlrtAssign(&c_y, m);
      d_y = NULL;
      m = emlrtCreateDoubleScalar(tol);
      emlrtAssign(&d_y, m);
      e_st.site = &gq_emlrtRSI;
      emlrt_marshallIn(&e_st, b_sprintf(&e_st, c_y, d_y, &p_emlrtMCI),
                       "<output of sprintf>", str);
      d_st.site = &wm_emlrtRSI;
      f_warning(&d_st, rankA, str);
    }

    c_st.site = &um_emlrtRSI;
    nb = B->size[1];
    minmn = B->size[1];
    array_real_T_2D_SetSize(Y, b_A.size[1], minmn);
    maxmn = b_A.size[1] * minmn;
    for (i = 0; i < maxmn; i++) {
      Y->vector.data[i] = 0.0;
    }

    d_st.site = &xm_emlrtRSI;
    e_st.site = &ym_emlrtRSI;
    array_real_T_2D_SetSize(&b_B, B->size[0], B->size[1]);
    maxmn = B->size[0] * B->size[1];
    for (i = 0; i < maxmn; i++) {
      b_B.vector.data[i] = B->vector.data[i];
    }

    if (b_A.size[0] < b_A.size[1]) {
      minmn = b_A.size[0];
    } else {
      minmn = b_A.size[1];
    }

    if ((b_A.size[0] != 0) && (b_A.size[1] != 0)) {
      nrc_t = (ptrdiff_t)b_B.size[0];
      nrc_t = LAPACKE_dormqr(102, 'L', 'T', nrc_t, (ptrdiff_t)b_B.size[1],
        (ptrdiff_t)minmn, &b_A.vector.data[0], (ptrdiff_t)b_A.size[0],
        &tau.vector.data[0], &b_B.vector.data[0], nrc_t);
      if ((int32_T)nrc_t != 0) {
        if (((int32_T)nrc_t == -10) && (b_B.size[1] > 1)) {
          if (b_A.size[0] < b_A.size[1]) {
            minmn = b_A.size[0];
          } else {
            minmn = b_A.size[1];
          }

          for (j = 0; j < minmn; j++) {
            maxmn = b_B.size[1];
            b_m = b_A.size[0];
            if (tau.vector.data[j] != 0.0) {
              for (k = 0; k < maxmn; k++) {
                tol = b_B.vector.data[j + b_B.size[0] * k];
                i = j + 2;
                for (b_i = i; b_i <= b_m; b_i++) {
                  tol += b_A.vector.data[(b_i + b_A.size[0] * j) - 1] *
                    b_B.vector.data[(b_i + b_B.size[0] * k) - 1];
                }

                tol *= tau.vector.data[j];
                if (tol != 0.0) {
                  b_B.vector.data[j + b_B.size[0] * k] -= tol;
                  i = j + 2;
                  for (b_i = i; b_i <= b_m; b_i++) {
                    b_B.vector.data[(b_i + b_B.size[0] * k) - 1] -=
                      b_A.vector.data[(b_i + b_A.size[0] * j) - 1] * tol;
                  }
                }
              }
            }
          }
        } else {
          for (i = 0; i < 2; i++) {
            c_B[i] = b_B.size[i];
          }

          array_real_T_2D_SetSize(&b_B, c_B[0], c_B[1]);
          maxmn = c_B[0] * c_B[1];
          for (i = 0; i < maxmn; i++) {
            b_B.vector.data[i] = rtNaN;
          }
        }
      }
    }

    for (k = 0; k < nb; k++) {
      for (b_i = 0; b_i < rankA; b_i++) {
        Y->vector.data[(jpvt.vector.data[b_i] + Y->size[0] * k) - 1] =
          b_B.vector.data[b_i + b_B.size[0] * k];
      }

      for (j = rankA; j >= 1; j--) {
        Y->vector.data[(jpvt.vector.data[j - 1] + Y->size[0] * k) - 1] /=
          b_A.vector.data[(j + b_A.size[0] * (j - 1)) - 1];
        for (b_i = 0; b_i <= j - 2; b_i++) {
          Y->vector.data[(jpvt.vector.data[b_i] + Y->size[0] * k) - 1] -=
            Y->vector.data[(jpvt.vector.data[j - 1] + Y->size[0] * k) - 1] *
            b_A.vector.data[b_i + b_A.size[0] * (j - 1)];
        }
      }
    }
  }

  array_ptrdiff_t_Destructor(&IPIV);
  array_real_T_2D_Destructor(&b_B);
  array_int32_T_2D_Destructor(&jpvt);
  array_real_T_Destructor(&tau);
  array_real_T_2D_Destructor(&b_A);
}

