static boolean_T isPositiveDefinite(const emlrtStack *sp, real_T B[144])
{
  static const int32_T iv[2] = { 1, 30 };

  static const int32_T iv1[2] = { 1, 30 };

  static char_T b_u[30] = { 'C', 'o', 'd', 'e', 'r', ':', 'b', 'u', 'i', 'l',
    't', 'i', 'n', 's', ':', 'A', 's', 's', 'e', 'r', 't', 'i', 'o', 'n', 'F',
    'a', 'i', 'l', 'e', 'd' };

  emlrtStack st;
  const mxArray *b_y;
  const mxArray *m;
  const mxArray *y;
  real_T A[144];
  int32_T info;
  int32_T n;
  char_T u[30];
  st.prev = sp;
  st.tls = sp->tls;
  memcpy(&A[0], &B[0], 144U * sizeof(real_T));
  st.site = &hn_emlrtRSI;
  chol(A, &info, &n);
  if (n > 12) {
    for (n = 0; n < 30; n++) {
      u[n] = b_u[n];
    }

    y = NULL;
    m = emlrtCreateCharArray(2, &iv[0]);
    emlrtInitCharArrayR2013a((emlrtConstCTX)sp, 30, m, &u[0]);
    emlrtAssign(&y, m);
    for (n = 0; n < 30; n++) {
      u[n] = b_u[n];
    }

    b_y = NULL;
    m = emlrtCreateCharArray(2, &iv1[0]);
    emlrtInitCharArrayR2013a((emlrtConstCTX)sp, 30, m, &u[0]);
    emlrtAssign(&b_y, m);
    st.site = &gp_emlrtRSI;
    b_error(&st, y, getString(&st, b_message(&st, b_y, &sb_emlrtMCI),
             &sb_emlrtMCI), &sb_emlrtMCI);
  }

  return info == 0;
}

static boolean_T DampedBFGSwGradientProjection_searchDirectionInvalid(const
  emlrtStack *sp, robotics_core_internal_DampedBFGSwGradientProjection *obj,
  real_T xNew[12])
{
  coder_array_boolean_T r1;
  coder_array_real_T r;
  coder_array_real_T_2D a;
  emlrtStack st;
  real_T d;
  int32_T aux_0_0;
  int32_T aux_1_0;
  int32_T i;
  int32_T loop_ub;
  int32_T stride_0_0;
  int32_T stride_1_0;
  boolean_T flag;
  st.prev = sp;
  st.tls = sp->tls;
  array_real_T_2D_Constructor(&a);
  array_real_T_Constructor(&r);
  array_boolean_T_Constructor(&r1);
  if (obj->ConstraintsOn) {
    array_real_T_2D_SetSize(&a, obj->ConstraintMatrix.size[0],
      obj->ConstraintMatrix.size[1]);
    loop_ub = obj->ConstraintMatrix.size[0] * obj->ConstraintMatrix.size[1];
    for (i = 0; i < loop_ub; i++) {
      a.vector.data[i] = obj->ConstraintMatrix.vector.data[i];
    }

    st.site = &fj_emlrtRSI;
    dynamic_size_checks(&st, &a, a.size[0]);
    st.site = &gj_emlrtRSI;
    d_mtimes(&a, xNew, &r);
    d = 2.2204460492503131E-16;
    st.site = &jn_emlrtRSI;
    b_sqrt(&d);
    if (obj->ConstraintBound.size[0] == 1) {
      i = r.size[0];
    } else {
      i = obj->ConstraintBound.size[0];
    }

    array_boolean_T_SetSize(&r1, i);
    stride_0_0 = (r.size[0] != 1);
    stride_1_0 = (obj->ConstraintBound.size[0] != 1);
    aux_0_0 = 0;
    aux_1_0 = 0;
    if (obj->ConstraintBound.size[0] == 1) {
      loop_ub = r.size[0];
    } else {
      loop_ub = obj->ConstraintBound.size[0];
    }

    for (i = 0; i < loop_ub; i++) {
      r1.vector.data[i] = (r.vector.data[aux_0_0] -
                           obj->ConstraintBound.vector.data[aux_1_0] >
                           1.4901161193847656E-8);
      aux_1_0 += stride_1_0;
      aux_0_0 += stride_0_0;
    }

    st.site = &jn_emlrtRSI;
    if (any(&st, &r1)) {
      flag = true;
    } else {
      flag = false;
    }
  } else {
    flag = false;
  }

  array_boolean_T_Destructor(&r1);
  array_real_T_Destructor(&r);
  array_real_T_2D_Destructor(&a);
  return flag;
}

